select count(*)
from sys_result
where date_format(create_time,'%Y-%m-%d') = #{s}
and u_id = #{userId}
and is_finish = 1

select is_finish
from sys_result
where u_id = #{uId}
and p_id = #{pId}
and step = 0
limit 1

select *
from sys_result
where u_id = #{uId}
and p_id = #{pId}
limit 1

select *
from sys_result
where DATE_FORMAT(update_time,'%Y') = #{num}
and u_id = #{uId}
and is_finish = 1

select distinct u_id
from sys_result
where p_id = #{pId}
and step >= #{step}
and (is_finish = 4
or is_finish = 1)

select sum(score)
from sys_result
where u_id = #{uId}
and p_id = #{pId}

select is_finish
from sys_result
where u_id = #{uId}
and p_id = #{pId}
limit 1

select distinct p_id
from sys_result
where u_id = #{uId}

select evidence
from sys_result
where u_id = #{uId}
and p_id = #{pId}

select distinct re.u_id
from sys_result re,sys_user_role ur
where re.p_id = #{pId}
and re.step >= #{step}
and (re.is_finish = 4
or re.is_finish = 1)
and ur.role_id = #{role}
and re.u_id = ur.user_id

select distinct u_id
from sys_result
